#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float dot_scale;       // 2..16
    float posterize;       // 2..16 levels
    float outline;         // 0..2
    float palette;         // 0=Roy,1=Warhol,2=Custom
    float customHue;       // 0..1
};

struct VIn { float4 pos [[attribute(0)]]; float2 uv [[attribute(1)]]; };
struct VOut { float4 pos [[position]]; float2 uv; };

vertex VOut main0(VIn in [[stage_in]], constant Uniforms &u [[buffer(0)]]) {
    VOut o; o.pos = u.MVP * in.pos; o.uv = in.uv; return o;
}

static inline float luma(float3 c){ return dot(c, float3(0.2126,0.7152,0.0722)); }
static inline float3 hsv2rgb(float3 c){ float4 K=float4(1.,2./3.,1./3.,3.); float3 p=abs(fract(c.xxx+K.xyz)*6.-K.www); return c.z*mix(K.xxx, clamp(p-K.xxx,0.,1.), c.y);} 

fragment float4 fragment_main(VOut in [[stage_in]], texture2d<float> src [[texture(0)]], constant Uniforms &u [[buffer(0)]]) {
    constexpr sampler s(address::clamp_to_edge, filter::linear);
    float2 pix = in.uv * u.OutputSize.xy;
    float3 c = src.sample(s, in.uv).rgb;

    // Posterize
    float levels = clamp(round(u.posterize), 2.0, 16.0);
    float3 pz = floor(c * levels) / (levels-1.0);

    // Palette remap
    float3 pal0 = float3(0.95,0.1,0.15);   // Roy red
    float3 pal1 = float3(0.05,0.15,0.85);  // Roy blue
    float3 pal2 = float3(0.98,0.98,0.1);   // Roy yellow
    float3 pal3 = float3(0.05,0.85,0.25);  // Roy green

    float3 mapped = pz;
    if (u.palette < 0.5) {
        // Roy: map luminance bands
        float L = luma(pz);
        mapped = (L < 0.25) ? pal1 : (L < 0.5) ? pal2 : (L < 0.75) ? pal0 : pal3;
    } else if (u.palette < 1.5) {
        // Warhol: hue shift blocks
        float2 block = floor(pix / (u.dot_scale*8.0));
        float hue = fract(dot(block, float2(0.319,0.173)));
        mapped = hsv2rgb(float3(hue, 0.8, max(pz.r, max(pz.g, pz.b))));
    } else {
        // Custom: hue slider
        mapped = hsv2rgb(float3(fract(u.customHue), 0.8, max(pz.r, max(pz.g, pz.b))));
    }

    // Halftone dots
    float scale = clamp(u.dot_scale, 2.0, 16.0);
    float2 cell = fract(pix/scale) - 0.5;
    float L = luma(pz);
    float rad = mix(0.05, 0.45, 1.0 - L);
    float d = length(cell) * 1.4142;
    float dotMask = 1.0 - smoothstep(rad-0.02, rad+0.02, d);

    // Outline via Sobel on luma
    float2 texel = 1.0 / u.OutputSize.xy;
    float gx=0.0, gy=0.0; int idx=0;
    float kx[9] = {-1,0,1,-2,0,2,-1,0,1}; float ky[9] = {-1,-2,-1,0,0,0,1,2,1};
    for(int j=-1;j<=1;++j){ for(int i=-1;i<=1;++i){
        float3 s3 = src.sample(s, in.uv + float2(i,j)*texel).rgb; float Ll = luma(s3);
        gx += Ll * kx[idx]; gy += Ll * ky[idx]; idx++; }}
    float edge = smoothstep(0.3, 0.9, length(float2(gx,gy)));

    float3 outc = mapped * dotMask;
    outc = mix(outc, float3(0.0), edge * u.outline);

    return float4(saturate(outc), 1.0);
}

